const root=document.querySelector('.fb-detail');
for(const picker of root.querySelectorAll('[data-fb-picker]')){const select=picker.querySelector('select');const panels=[...picker.children].filter(x=>x.hasAttribute('data-fb-option'));select.addEventListener('change',()=>{panels.forEach(x=>x.hidden=x.dataset.fbOption!==select.value);});}
for(const manager of root.querySelectorAll('[data-fb-manager]')){const buttons=[...manager.querySelectorAll('[data-config-step]')];function show(button){buttons.forEach(b=>{const active=b===button;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;});manager.querySelectorAll('[data-config-panel]').forEach(p=>p.hidden=p.dataset.configPanel!==button.dataset.configStep);}buttons.forEach((button,i)=>{button.addEventListener('click',()=>show(button));button.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight')next=(i+1)%buttons.length;if(event.key==='ArrowLeft')next=(i+buttons.length-1)%buttons.length;if(event.key==='Home')next=0;if(event.key==='End')next=buttons.length-1;if(next!==undefined){event.preventDefault();show(buttons[next]);buttons[next].focus();}});});}
root.querySelectorAll('[data-fb-route]').forEach(a=>a.addEventListener('click',()=>{const select=root.querySelector('#fb-setup');select.value=a.dataset.fbRoute;select.dispatchEvent(new Event('change'));}));
root.querySelectorAll('[data-fs-goal]').forEach(button=>button.addEventListener('click',()=>{root.querySelectorAll('[data-fs-goal]').forEach(b=>{const selected=b===button;b.setAttribute('aria-pressed',String(selected));b.querySelector('span').textContent=selected?'●':'○';});root.querySelectorAll('[data-fs-goal-panel]').forEach(p=>p.hidden=p.dataset.fsGoalPanel!==button.dataset.fsGoal);}));
const checks=[...root.querySelectorAll('[data-fs-check]')];checks.forEach(c=>c.addEventListener('change',()=>{root.querySelector('.fs-check-status').textContent=`Đã kiểm tra ${checks.filter(x=>x.checked).length}/${checks.length} mục trong mô phỏng.`;}));
const fd=root.querySelector('.fd-gallery');if(fd){const tabs=[...fd.querySelectorAll('[data-fd-tab]')];const activate=t=>{tabs.forEach(b=>{b.setAttribute('aria-selected',String(b===t));b.tabIndex=b===t?0:-1;});fd.querySelectorAll('[data-fd-panel]').forEach(p=>p.hidden=p.dataset.fdPanel!==t.dataset.fdTab);};tabs.forEach((t,i)=>{t.addEventListener('click',()=>activate(t));t.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();activate(tabs[n]);tabs[n].focus();}});});fd.querySelectorAll('.fd-video').forEach(v=>v.querySelectorAll('[data-fd-frame-button]').forEach(b=>b.addEventListener('click',()=>{v.querySelectorAll('[data-fd-frame]').forEach(x=>x.hidden=x.dataset.fdFrame!==b.dataset.fdFrameButton);v.querySelectorAll('[data-fd-frame-button]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));})));fd.querySelectorAll('.fd-carousel').forEach(c=>{let index=0;const cards=[...c.querySelectorAll('[data-fd-card]')];c.querySelectorAll('[data-fd-slide]').forEach(b=>b.addEventListener('click',()=>{index=(index+Number(b.dataset.fdSlide)+cards.length)%cards.length;cards.forEach((x,i)=>x.hidden=i!==index);c.querySelector('output').textContent=`${index+1} / ${cards.length}`;}));});fd.querySelectorAll('[data-fd-panel]').forEach(panel=>{const outcome=panel.querySelector('[data-fd-outcome]');const show=kind=>{outcome.hidden=false;outcome.querySelector('[data-fd-contact-panel]').hidden=kind!=='contact';outcome.querySelector('[data-fd-shop-panel]').hidden=kind!=='shop';outcome.querySelector('[data-fd-close]').focus();};panel.querySelectorAll('[data-fd-contact]').forEach(b=>b.addEventListener('click',()=>show('contact')));panel.querySelectorAll('[data-fd-shop]').forEach(b=>b.addEventListener('click',()=>show('shop')));outcome.querySelector('[data-fd-close]').addEventListener('click',()=>{outcome.hidden=true;panel.querySelector('[data-fd-contact],[data-fd-shop]')?.focus();});});}
root.querySelectorAll('.fe-scene').forEach(scene=>{scene.querySelectorAll('[data-fe-choice]').forEach(b=>b.addEventListener('click',()=>{scene.querySelectorAll('[data-fe-choice]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));scene.querySelectorAll('[data-fe-panel]').forEach(p=>p.hidden=p.dataset.fePanel!==b.dataset.feChoice);}));scene.querySelectorAll('[data-fe-settings]').forEach(b=>b.addEventListener('click',()=>{const details=scene.nextElementSibling;details.open=true;details.scrollIntoView({block:'start',behavior:'smooth'});}));});
